name: Updater Installed Client E2E

on:
  workflow_dispatch:
  push:
    branches:
      - main
    paths:
      - '.github/workflows/updater-installed-client-e2e.yml'
      - 'tests/MhwModManager.IntegrationTests/MhwModManager.IntegrationTests.csproj'
      - 'tests/MhwModManager.IntegrationTests/UpdaterInstalledClientE2ETests.cs'
      - 'tests/MhwModManager.IntegrationTests/UpdateInstallerTests.cs'
      - 'src/MhwModManager.Updater/**'
      - 'src/MhwModManager.Updater.Helper/**'
      - 'src/MhwModManager.App/App.xaml.cs'
  pull_request:
    paths:
      - '.github/workflows/updater-installed-client-e2e.yml'
      - 'tests/MhwModManager.IntegrationTests/UpdaterInstalledClientE2ETests.cs'
      - 'tests/MhwModManager.IntegrationTests/UpdateInstallerTests.cs'
      - 'src/MhwModManager.Updater/**'
      - 'src/MhwModManager.Updater.Helper/**'
      - 'src/MhwModManager.App/App.xaml.cs'

permissions:
  contents: write

jobs:
  installed-client-e2e:
    name: Real packaged 60 to 61 update and rollback
    runs-on: windows-latest
    timeout-minutes: 20
    env:
      MHW_RUN_UPDATER_INSTALLED_E2E: '1'
      MHW_MOD_MANAGER_GITHUB_TOKEN: ${{ github.token }}
      MHW_E2E_EVIDENCE_PATH: ${{ github.workspace }}\BuildLogs\updater-installed-e2e\evidence.json

    steps:
      - name: Check out candidate
        uses: actions/checkout@v7

      - name: Install pinned .NET SDK
        uses: actions/setup-dotnet@v6
        with:
          dotnet-version: 10.0.401

      - name: Prepare evidence directory
        shell: powershell
        run: |
          $evidence = Split-Path -Parent $env:MHW_E2E_EVIDENCE_PATH
          New-Item -ItemType Directory -Force -Path $evidence | Out-Null
          @(
            "candidate_sha=$env:GITHUB_SHA"
            "runner_os=$env:RUNNER_OS"
            "runner_arch=$env:RUNNER_ARCH"
            "dotnet_sdk=$(& dotnet --version)"
            "run_opt_in=$env:MHW_RUN_UPDATER_INSTALLED_E2E"
          ) | Set-Content -LiteralPath (Join-Path $evidence 'provenance.txt') -Encoding UTF8
          if ($env:MHW_RUN_UPDATER_INSTALLED_E2E -ne '1') {
            throw 'Updater installed-client E2E opt-in is not active.'
          }
          if ([string]::IsNullOrWhiteSpace($env:MHW_MOD_MANAGER_GITHUB_TOKEN)) {
            throw 'Repository token was not supplied to the updater E2E.'
          }

      - name: Restore integration test project
        shell: powershell
        run: |
          dotnet restore .\tests\MhwModManager.IntegrationTests\MhwModManager.IntegrationTests.csproj -p:NuGetAudit=false
          if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }

      - name: Build integration test project
        shell: powershell
        run: |
          dotnet build .\tests\MhwModManager.IntegrationTests\MhwModManager.IntegrationTests.csproj -c Release --no-restore -p:NuGetAudit=false
          if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }

      - name: Run full integration suite including updater E2E and ownership regressions
        shell: powershell
        run: |
          $evidence = Split-Path -Parent $env:MHW_E2E_EVIDENCE_PATH
          $log = Join-Path $evidence 'runtime-ownership-tests.log'
          $runner = '.\tests\MhwModManager.IntegrationTests\bin\Release\net10.0-windows10.0.19041.0\MhwModManager.IntegrationTests.exe'
          if (!(Test-Path -LiteralPath $runner)) {
            throw "Built xUnit v3 integration runner is missing: $runner"
          }
          & $runner 2>&1 |
            Tee-Object -FilePath $log
          $exit = $LASTEXITCODE
          if ($exit -ne 0) { exit $exit }
          if (!(Test-Path -LiteralPath $env:MHW_E2E_EVIDENCE_PATH)) {
            throw 'Full integration suite returned success without producing updater E2E evidence.json.'
          }
          Copy-Item -LiteralPath $log -Destination (Join-Path $evidence 'installed-client-e2e-test.log') -Force

      - name: Verify updater success and rollback evidence
        shell: powershell
        run: |
          $evidenceDir = Split-Path -Parent $env:MHW_E2E_EVIDENCE_PATH
          $log = Join-Path $evidenceDir 'rollback-regression-tests.log'
          if (!(Test-Path -LiteralPath $env:MHW_E2E_EVIDENCE_PATH)) {
            throw 'Updater E2E evidence.json is missing.'
          }
          $doc = Get-Content -LiteralPath $env:MHW_E2E_EVIDENCE_PATH -Raw | ConvertFrom-Json
          if ($doc.status -eq 'FAIL') {
            throw "Updater E2E evidence reports failure: $($doc.failureType): $($doc.failureMessage)"
          }
          if ($doc.scenarioA.status -ne 'PASS') {
            throw "Installed-client update scenario did not pass: $($doc.scenarioA.status)"
          }
          if ($doc.scenarioB.status -ne 'PASS') {
            throw "Injected rollback scenario did not pass: $($doc.scenarioB.status)"
          }
          @(
            'full_integration_suite=PASS'
            ('scenarioA=' + $doc.scenarioA.status)
            ('scenarioB=' + $doc.scenarioB.status)
            ('restoredBuild=' + $doc.scenarioB.restoredBuild)
            ('restoredSource=' + $doc.scenarioB.restoredSource)
          ) | Set-Content -LiteralPath $log -Encoding UTF8
